INSERT INTO public.accounting_bank_match (movement_key, operation_date, amount_cents, concept, targets)
SELECT v.movement_key, v.operation_date, v.amount_cents, 'Cierre del 02/11/2026', v.targets
  FROM v
 WHERE (SELECT count(*) FROM public.billing_payment p JOIN payments USING (id)) = 349
ON CONFLICT (movement_key) DO NOTHING;
